<script setup lang="ts">
import {computed} from 'vue';import type {EditorController} from '../controller.ts';import type {Marker} from '../../../../packages/core/src/markers.ts';import {targetTimeAt} from '../../../../packages/core/src/animation.ts';import {toNumber} from '../../../../packages/core/src/time.ts';import {timecode} from '../controller.ts';
const props=defineProps<{c:EditorController;open:boolean}>();const emit=defineEmits<{'update:open':[boolean]}>();
const rows=computed(()=>{const d=props.c.doc.value;if(!d)return [];return [...(d.markers||[]).map(marker=>({marker,clipId:undefined as string|undefined,trackLocked:false,owner:'时间线',time:toNumber(marker.time)})),...d.tracks.flatMap(t=>t.clips.flatMap(clip=>(clip.markers||[]).map(marker=>({marker,clipId:clip.id,trackLocked:!!t.locked,owner:d.assets.find(a=>a.id===clip.materialId)?.name||'片段',time:toNumber(targetTimeAt(clip,marker.time))}))))].sort((a,b)=>a.time-b.time);});
function update(marker:Marker,clipId:string|undefined,changes:Partial<Marker>){return props.c.guard(()=>props.c.edit({type:'marker.set',clipId,marker:{...marker,...changes}}));}
function jump(time:number){props.c.playing.value=false;props.c.seek(time);emit('update:open',false);}
</script>
<template><a-modal :open="open" title="标记" :width="760" :footer="null" :get-container="false" @update:open="emit('update:open',$event)"><div class="marker-manager"><article v-for="row in rows" :key="(row.clipId||'timeline')+row.marker.id"><button class="marker-time" @click="jump(row.time)">{{timecode(row.time,c.doc.value?toNumber(c.doc.value.fps):30)}}</button><span class="marker-owner" :title="row.owner">{{row.owner}}</span><a-input :value="row.marker.title" aria-label="标记名称" :maxlength="100" :disabled="c.readOnly.value||row.trackLocked" @blur="(e:any)=>e.target.value!==row.marker.title&&update(row.marker,row.clipId,{title:e.target.value})" /><input type="color" aria-label="标记颜色" :value="row.marker.color" :disabled="c.readOnly.value||row.trackLocked" @change="(e:any)=>update(row.marker,row.clipId,{color:e.target.value})" /><a-button :disabled="c.busy.value||c.readOnly.value||row.trackLocked" @click="c.guard(()=>c.edit({type:'marker.remove',clipId:row.clipId,markerId:row.marker.id}))">删除</a-button></article><p v-if="!rows.length" class="quiet">将播放头移到需要的位置，点击标记按钮或按 M 添加标记。</p></div></a-modal></template>
